if (programId == null) return null
def key = programId.toString().trim()
if (key.isEmpty()) return null

def tableOid = '7c3f2a91-4e8d-4b16-9a52-6d0e1f7b3c48'

try {
    def options = com.evolveum.midpoint.schema.SelectorOptions.createCollection(
        prismContext.toUniformPath(com.evolveum.midpoint.xml.ns._public.common.common_3.LookupTableType.F_ROW),
        com.evolveum.midpoint.schema.GetOperationOptions.createRetrieve()
    )
    def tableObj = midpoint.getObject(com.evolveum.midpoint.xml.ns._public.common.common_3.LookupTableType.class, tableOid, options)
    if (tableObj == null) {
        log.warn('sb-program-resolver-byid: LookupTable {} not found', tableOid)
        return null
    }
    def rows = tableObj.getRow()
    if (rows == null || rows.isEmpty()) {
        log.warn('sb-program-resolver-byid: LookupTable {} has no rows', tableOid)
        return null
    }

    for (def row : rows) {
        if (row.getKey() != null && row.getKey().trim() == key) {
            return row.getValue()
        }
    }

    log.debug('sb-program-resolver-byid: no anchor in thesaurus for ID_PROGRAMA_ESTUDIO={}', key)
    return null
} catch (Exception e) {
    log.warn('sb-program-resolver-byid: error resolving id "{}": {}', key, e.getMessage())
    return null
}

if (programId == null) return null
def key = programId.toString().trim()
if (key.isEmpty()) return null

def tableOid = '7c3f2a91-4e8d-4b16-9a52-6d0e1f7b3c48'

try {
    def options = com.evolveum.midpoint.schema.SelectorOptions.createCollection(
        prismContext.toUniformPath(com.evolveum.midpoint.xml.ns._public.common.common_3.LookupTableType.F_ROW),
        com.evolveum.midpoint.schema.GetOperationOptions.createRetrieve()
    )
    def tableObj = midpoint.getObject(com.evolveum.midpoint.xml.ns._public.common.common_3.LookupTableType.class, tableOid, options)
    if (tableObj == null) return null
    def rows = tableObj.getRow()
    if (rows == null) return null

    for (def row : rows) {
        if (row.getKey() != null && row.getKey().trim() == key) {
            def lab = row.getLabel()
            if (lab != null) return lab.getOrig()
            return null
        }
    }
    return null
} catch (Exception e) {
    log.warn('sb-program-resolver-byid.resolveProgramCodeById: error "{}" -> {}', key, e.getMessage())
    return null
}
